import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def dfs(tree, n, leaf_time):
    visited = [False] * (n + 1)
    farthest_dist = [0] * (n + 1)
    queue = deque([1])
    visited[1] = True

    while queue:
        node = queue.popleft()
        for neighbor, weight in tree[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                farthest_dist[neighbor] = farthest_dist[node] + weight
                queue.append(neighbor)

    max_leaf_time = max(farthest_dist[1:])
    return max_leaf_time

def main():
    n = int(sys.stdin.readline().strip())
    tree = defaultdict(list)

    for _ in range(n - 1):
        x, y, v = read_ints()
